// Some portions generated by Claude
import assert from "node:assert/strict";
import test from "node:test";
import { mergeTriples } from "../../../main/frontend/graph-explorer/graph-operations.ts";
import { bindingsToTriples } from "../../../main/frontend/graph-explorer/graph-terms.ts";
import {
  RELATION_CONFIRM_LINKS,
  loadedRelationLinks,
  relationChunks,
  relationCountCap,
  relationLimits,
  relationPlan,
} from "../../../main/frontend/graph-explorer/relation-expansion.ts";
import { neighborsQuery, relationCountQuery } from "../../../main/frontend/graph-explorer/rdf-vocabulary.ts";

// "Expand by relation" loads every link of the chosen relation; above RELATION_CONFIRM_LINKS new links it asks first
// and lets the user choose how many, in total or per selected node.
const CHARACTER = "urn:sw:character";
const uri = (value) => ({ type: "uri", value });

test("more than 100 new links in total are asked about", () => {
  assert.equal(RELATION_CONFIRM_LINKS, 100);
});

test("the links to load are each node's links in the repository less the ones the graph holds", () => {
  const counts = new Map([["urn:film:1", 18], ["urn:film:5", 40], ["urn:film:7", 11], ["urn:film:9", 0]]);
  const loaded = new Map([["urn:film:1", 12], ["urn:film:5", 12], ["urn:film:7", 11]]);
  assert.deepEqual(relationPlan(counts, loaded, 999), {
    available: new Map([["urn:film:1", 6], ["urn:film:5", 28]]),
    total: 34,
    atLeast: false,
    capped: new Set(),
  });
  // A count past the cap is only a lower bound.
  assert.deepEqual(relationPlan(new Map([["urn:hub", 1000], ["urn:a", 3]]), new Map([["urn:hub", 10]]), 999), {
    available: new Map([["urn:hub", 990], ["urn:a", 3]]),
    total: 993,
    atLeast: true,
    capped: new Set(["urn:hub"]),
  });
});

test("a node counted past the cap may load more than it was counted with", () => {
  const available = new Map([["hub", 990], ["a", 3]]);
  const capped = new Set(["hub"]);
  assert.deepEqual(relationLimits(available, { mode: "perNode", amount: 5000 }, capped), new Map([["hub", 5000], ["a", 3]]));
  assert.deepEqual(relationLimits(available, { mode: "total", amount: 5000 }, capped), new Map([["hub", 4997], ["a", 3]]));
  assert.deepEqual(relationLimits(available, { mode: "total", amount: 5000 }), new Map([["hub", 990], ["a", 3]]));
});

test("a total is shared evenly: small nodes load everything, the rest split what is left", () => {
  // What does not divide evenly goes to the nodes with the most links.
  const available = new Map([["a", 18], ["b", 40], ["c", 11], ["d", 34]]);
  assert.deepEqual(relationLimits(available, { mode: "total", amount: 60 }), new Map([["a", 16], ["b", 17], ["c", 11], ["d", 16]]));
  assert.deepEqual(relationLimits(available, { mode: "total", amount: 1000 }), available, "more than there is: everything");
  assert.deepEqual(relationLimits(available, { mode: "total", amount: 2 }), new Map([["b", 1], ["d", 1]]));
  const sum = (limits) => [...limits.values()].reduce((total, value) => total + value, 0);
  for (const amount of [1, 7, 44, 59, 102, 103]) assert.equal(sum(relationLimits(available, { mode: "total", amount })), amount);
});

test("per node, every node loads up to the amount", () => {
  const available = new Map([["a", 18], ["b", 40], ["c", 11]]);
  assert.deepEqual(relationLimits(available, { mode: "perNode", amount: 15 }), new Map([["a", 15], ["b", 15], ["c", 11]]));
  assert.deepEqual(relationLimits(available, { mode: "perNode", amount: 0 }), new Map());
  assert.deepEqual(relationLimits(available, { mode: "total", amount: Number.NaN }), new Map());
});

test("the graph's links of one relation, per node and direction", () => {
  const graph = mergeTriples(
    { nodes: [], edges: [], revision: 0 },
    bindingsToTriples([
      { source: uri("urn:film:1"), predicate: uri(CHARACTER), target: uri("urn:luke") },
      { source: uri("urn:film:1"), predicate: uri(CHARACTER), target: uri("urn:leia") },
      { source: uri("urn:film:1"), predicate: uri("urn:sw:planet"), target: uri("urn:tatooine") },
      { source: uri("urn:film:2"), predicate: uri(CHARACTER), target: uri("urn:luke") },
      { source: uri("urn:luke"), predicate: uri(CHARACTER), target: uri("urn:film:1") },
    ]),
  );
  const outgoing = loadedRelationLinks(graph, ["urn:film:1", "urn:film:2", "urn:film:3"], CHARACTER, "outgoing");
  assert.deepEqual(outgoing.counts, new Map([["urn:film:1", 2], ["urn:film:2", 1], ["urn:film:3", 0]]));
  // The node's loaded links, as Expand leaves them out; neighborsQuery keeps those of the relation it loads.
  assert.deepEqual(outgoing.loaded.get("urn:film:1").outgoing,
    [[`<${CHARACTER}>`, "<urn:luke>"], [`<${CHARACTER}>`, "<urn:leia>"], ["<urn:sw:planet>", "<urn:tatooine>"]]);
  assert.deepEqual(outgoing.loaded.get("urn:film:1").incoming, [["<urn:luke>", `<${CHARACTER}>`]]);
  const incoming = loadedRelationLinks(graph, ["urn:film:1"], CHARACTER, "incoming");
  assert.deepEqual(incoming.counts, new Map([["urn:film:1", 1]]));
  assert.deepEqual(incoming.loaded.get("urn:film:1").incoming, [["<urn:luke>", `<${CHARACTER}>`]]);
});

test("neighbours load without a cap, with a limit per node, and after the loaded ones", () => {
  const unlimited = neighborsQuery(["urn:a", "urn:b"], CHARACTER, "outgoing", null, "default", true);
  assert.doesNotMatch(unlimited, /LIMIT/);
  assert.equal(unlimited.match(/SELECT DISTINCT/g).length, 2);

  const shared = neighborsQuery(["urn:a", "urn:b"], CHARACTER, "outgoing", new Map([["urn:a", 16], ["urn:b", 3]]), "default", true);
  assert.deepEqual(shared.match(/LIMIT \d+/g), ["LIMIT 16", "LIMIT 3"]);
  assert.throws(() => neighborsQuery(["urn:a", "urn:c"], CHARACTER, "outgoing", new Map([["urn:a", 2]]), "default"));

  const more = neighborsQuery(["urn:a"], CHARACTER, "outgoing", null, "default", true, new Map([["urn:a", {
    outgoing: [[`<${CHARACTER}>`, "<urn:luke>"], ["<urn:sw:planet>", "<urn:tatooine>"]],
    incoming: [["<urn:x>", `<${CHARACTER}>`]],
  }]]));
  assert.match(more, new RegExp(`MINUS \\{ VALUES \\(\\?predicate \\?target\\) \\{ \\(<${CHARACTER}> <urn:luke>\\) \\} \\}`));
  assert.doesNotMatch(more, /tatooine|urn:x/, "only this relation's loaded links, in its direction");
  assert.ok(more.indexOf("MINUS") > more.indexOf("AS ?predicate"), "?predicate is bound before the loaded links are left out");
});

test("relation counts stop one past the cap, per node", () => {
  const query = relationCountQuery(["urn:a", "urn:b"], CHARACTER, "incoming", 999, "default", true);
  assert.equal(query.match(/COUNT\(\*\) AS \?links/g).length, 2);
  assert.equal(query.match(/LIMIT 1000/g).length, 2);
  assert.match(query, new RegExp(`\\?source <${CHARACTER}> \\?target`));
  assert.match(query, /BIND\(\?selected AS \?target\)/);
  assert.match(query, /GROUP BY \?selected/);
  assert.throws(() => relationCountQuery(["urn:a"], CHARACTER, "incoming", 0, "default"));
});

test("counting goes past what the graph already holds, so loaded links never read as all of them", () => {
  // 1,200 loaded links of a hub against a count stopping at 1,000 would say there is nothing left to load.
  assert.equal(relationCountCap(new Map([["hub", 1200], ["a", 3]]), 999), 2199);
  assert.equal(relationCountCap(new Map(), 999), 999);
  assert.equal(relationCountCap(new Map([["hub", 500000]]), 999), 100000, "the count query's own bound");
  const plan = relationPlan(new Map([["hub", 2200]]), new Map([["hub", 1200]]), 2199);
  assert.deepEqual([plan.total, plan.atLeast], [1000, true]);
});

test("loads are split so that no request asks for more rows than the server sends", () => {
  const expected = new Map([["a", 3000], ["b", 3000], ["c", 10], ["d", 9000], ["e", 1990]]);
  // In selection order; a node with more rows than the cap goes alone (and the server cuts it).
  assert.deepEqual(relationChunks(["a", "b", "c", "d", "e"], expected, 5000), [["a"], ["b", "c"], ["d"], ["e"]]);
  const many = Array.from({ length: 100 }, (_, index) => `n${index}`);
  assert.deepEqual(relationChunks(many, new Map(many.map((id) => [id, 1])), 5000).map((chunk) => chunk.length), [64, 36]);
  assert.deepEqual(relationChunks(many, new Map(), undefined).map((chunk) => chunk.length), [64, 36], "no known cap");
});
